def kv_cache_bytes(layers, kv_heads, head_dim, bytes_per_value, tokens):
    return 2 * layers * kv_heads * head_dim * bytes_per_value * tokens

def admit_batch(requests, config, model):
    if len(requests) > config.max_batch_size:
        return False, 'MAX_BATCH_SIZE_EXCEEDED'
    total = sum(kv_cache_bytes(model.layers, model.kv_heads, model.head_dim, config.bytes_per_value, r.prompt_tokens + r.output_tokens) for r in requests)
    if total > config.kv_memory_budget_bytes:
        return False, 'KV_CACHE_BUDGET_EXCEEDED'
    return True, 'ADMITTED'
